<section class="form-panel wide"><h1><?= $id ? 'Consultar / editar' : 'Crear' ?> noticia</h1><p>La imagen es opcional: JPEG, PNG o WebP; máximo 2 MiB. El contenido se presenta como texto.</p><?php if ($errors): ?><p role="alert" class="error">Revise los campos indicados. Los textos introducidos se conservaron; vuelva a seleccionar la imagen.</p><?php endif ?><form method="post" enctype="multipart/form-data"><input type="hidden" name="_token" value="<?= e(csrf()) ?>">
<?php foreach (['title' => 'Título', 'summary' => 'Resumen', 'content' => 'Contenido', 'image_alt' => 'Texto alternativo de la imagen'] as $field => $label): ?><label for="<?= $field ?>"><?= $label ?></label><?php if (in_array($field, ['summary', 'content'], true)): ?><textarea id="<?= $field ?>" name="<?= $field ?>" rows="<?= $field === 'content' ? 10 : 3 ?>" required aria-describedby="<?= $field ?>-error" <?= isset($errors[$field]) ? 'aria-invalid="true"' : '' ?>><?= e($data[$field]) ?></textarea><?php else: ?><input id="<?= $field ?>" name="<?= $field ?>" <?= $field === 'title' ? 'required maxlength="160"' : 'maxlength="180"' ?> value="<?= e($data[$field]) ?>" aria-describedby="<?= $field ?>-error" <?= isset($errors[$field]) ? 'aria-invalid="true"' : '' ?>><?php endif ?><p id="<?= $field ?>-error" class="error"><?= e($errors[$field] ?? '') ?></p><?php endforeach ?>
<label for="category_id">Categoría</label><select id="category_id" name="category_id" required aria-describedby="category_id-error" <?= isset($errors['category_id']) ? 'aria-invalid="true"' : '' ?>><option value="">Seleccione</option><?php foreach ($categories as $c): ?><option value="<?= e($c['id']) ?>" <?= (string)$data['category_id'] === (string)$c['id'] ? 'selected' : '' ?>><?= e($c['name']) ?></option><?php endforeach ?></select><p id="category_id-error" class="error"><?= e($errors['category_id'] ?? '') ?></p>
<label for="image">Imagen <?= $data['image'] ? '(seleccionar reemplaza la actual)' : '' ?></label><input type="file" id="image" name="image" accept="image/jpeg,image/png,image/webp" aria-describedby="image-error" <?= isset($errors['image']) ? 'aria-invalid="true"' : '' ?>><p id="image-error" class="error"><?= e($errors['image'] ?? '') ?></p>
<?php if ($data['image']): ?><img class="preview" src="<?= e(($GLOBALS['config']['base_url'] ?? '') . '/uploads/' . $data['image']) ?>" alt="<?= e($data['image_alt']) ?>"><?php endif ?>
<label for="status">Estado</label><select id="status" name="status" aria-describedby="status-error" <?= isset($errors['status']) ? 'aria-invalid="true"' : '' ?>><option value="draft" <?= $data['status'] === 'draft' ? 'selected' : '' ?>>Borrador</option><option value="published" <?= $data['status'] === 'published' ? 'selected' : '' ?>>Publicado</option></select><p id="status-error" class="error"><?= e($errors['status'] ?? '') ?></p>
<?php if ($id): ?><p>Creación: <?= e($data['created_at']) ?> · Actualización: <?= e($data['updated_at']) ?></p><?php endif ?><button>Guardar noticia</button> <a href="<?= e(url('news')) ?>">Cancelar</a></form></section>
